264	// ---------------------------------------------------------------------------
265	// Types
266	// ---------------------------------------------------------------------------
267	
268	type ActionData =
269	  | { ok: true; message: string; redirectId?: string }
270	  | { error: string };
271	
272	// ---------------------------------------------------------------------------
273	// Constants
274	// ---------------------------------------------------------------------------
275	
276	const CATEGORY_LABELS: Record<string, string> = {
277	  tops: "Tops",
278	  bottoms: "Bottoms",
279	  dresses: "Dresses",
280	  shoes: "Shoes",
281	  kids: "Kids",
282	  rings: "Rings",
283	  sportswear: "Sportswear",
284	  general: "General",
285	};
286	
287	const CATEGORY_ICONS: Record<string, string> = {
288	  tops: "👕",
289	  bottoms: "👖",
290	  dresses: "👗",
291	  shoes: "👟",
292	  kids: "🧒",
293	  rings: "💍",
294	  sportswear: "🏃",
295	  general: "📏",
296	};
297	
298	const CATEGORY_SELECT_OPTIONS = [
299	  { label: "General", value: "general" },
300	  { label: "Tops", value: "tops" },
301	  { label: "Bottoms", value: "bottoms" },
302	  { label: "Dresses", value: "dresses" },
303	  { label: "Shoes", value: "shoes" },
304	  { label: "Kids", value: "kids" },
305	  { label: "Rings", value: "rings" },
306	  { label: "Sportswear", value: "sportswear" },
307	];
308	
309	// ---------------------------------------------------------------------------
310	// Helpers
311	// ---------------------------------------------------------------------------
312	
313	function formatDate(date: string | Date): string {
314	  return new Date(date).toLocaleDateString("en-US", {
315	    month: "short",
316	    day: "numeric",
317	    year: "numeric",
318	  });
319	}
320	
321	// ---------------------------------------------------------------------------
322	// Sub-components
323	// ---------------------------------------------------------------------------
324	
325	interface TemplateSectionProps {
326	  templates: Array<{ name: string; category: string; gender: string; rowCount: number }>;
327	  categories: string[];
328	  isLoading: boolean;
329	  onClose: () => void;
330	  fetcher: ReturnType<typeof useFetcher<typeof action>>;
331	}
332	
333	function TemplatePicker({ templates, categories, isLoading, fetcher }: TemplateSectionProps) {
334	  const [selectedCategory, setSelectedCategory] = useState<string>("all");
335	
336	  const filteredTemplates = selectedCategory === "all"
337	    ? templates
338	    : templates.filter((t) => t.category === selectedCategory);
339	
340	  return (
341	    <BlockStack gap="400">
342	      {/* Category filter */}
343	      <ButtonGroup variant="segmented">
344	        <Button
345	          variant={selectedCategory === "all" ? "primary" : undefined}
346	          onClick={() => setSelectedCategory("all")}
347	        >
348	          All
349	        </Button>
350	        {categories.map((cat) => (
351	          <Button
352	            key={cat}
353	            variant={selectedCategory === cat ? "primary" : undefined}
354	            onClick={() => setSelectedCategory(cat)}
355	          >
356	            {CATEGORY_ICONS[cat] ?? "📏"} {CATEGORY_LABELS[cat] ?? cat}
357	          </Button>
358	        ))}
359	      </ButtonGroup>
360	
361	      {/* Blank chart */}
362	      <Card>
363	        <InlineStack gap="400" align="space-between" blockAlign="center">
364	          <BlockStack gap="100">
365	            <Text as="p" variant="bodyMd" fontWeight="bold">Blank chart</Text>
366	            <Text as="p" variant="bodyMd" tone="subdued">
367	              Start with an empty table — add your own columns and sizes
368	            </Text>
369	          </BlockStack>
370	          <fetcher.Form method="post">
371	            <input type="hidden" name="intent" value="create-blank" />
372	            <input type="hidden" name="name" value="Untitled Size Chart" />
373	            <input type="hidden" name="category" value="general" />
374	            <Button submit loading={isLoading}>Create blank</Button>
375	          </fetcher.Form>
376	        </InlineStack>
377	      </Card>
378	
379	      {/* Template grid */}
380	      {filteredTemplates.length > 0 ? (
381	        <InlineGrid columns={{ xs: 1, sm: 2, md: 3 }} gap="400">
382	          {filteredTemplates.map((template) => (
383	            <Card key={template.name}>
384	              <BlockStack gap="200">
385	                <InlineStack gap="200" blockAlign="center">
386	                  <Text as="span" variant="bodyMd">{CATEGORY_ICONS[template.category] ?? "📏"}</Text>
387	                  <Text as="p" variant="bodyMd" fontWeight="bold">{template.name}</Text>
388	                </InlineStack>
389	                <InlineStack gap="200">
390	                  <Badge tone="info">{CATEGORY_LABELS[template.category] ?? template.category}</Badge>
391	                  <Text as="span" variant="bodyMd" tone="subdued">{template.rowCount} sizes</Text>
392	                </InlineStack>
393	                <fetcher.Form method="post">
394	                  <input type="hidden" name="intent" value="create-from-template" />
395	                  <input type="hidden" name="templateName" value={template.name} />
396	                  <Button variant="primary" submit loading={isLoading}>
397	                    Use template
398	                  </Button>
399	                </fetcher.Form>
400	              </BlockStack>
401	            </Card>
402	          ))}
403	        </InlineGrid>
404	      ) : (
405	        <Text as="p" variant="bodyMd" tone="subdued">No templates in this category.</Text>
406	      )}
407	    </BlockStack>
408	  );
409	}
