108	
109	export const action = async ({ request, params }: ActionFunctionArgs) => {
110	  const { session } = await authenticate.admin(request);
111	  const shop = session.shop;
112	  const id = params.id;
113	  if (!id) return { error: "Missing chart ID" };
114	  const formData = await request.formData();
115	  const intent = formData.get("intent") as string;
116	
117	  try {
118	    switch (intent) {
119	      case "save": {
120	        const name = formData.get("name") as string;
121	        const category = formData.get("category") as string;
122	        const status = formData.get("status") as string;
123	        const dataRaw = formData.get("data") as string;
124	
125	        if (!name?.trim()) return { error: "Chart name is required" };
126	
127	        let parsedData: ChartData;
128	        try {
129	          parsedData = JSON.parse(dataRaw) as ChartData;
130	        } catch {
131	          return { error: "Invalid chart data. Please try again." };
132	        }
133	
134	        if (id === "new") {
135	          const chart = await db.sizeChart.create({
136	            data: {
137	              shop,
138	              name: name.trim(),
139	              category,
140	              status,
141	              data: JSON.stringify(parsedData),
142	            },
143	          });
144	          return redirect(`/app/size-charts/${chart.id}?saved=1`);
145	        }
146	
147	        const existing = await db.sizeChart.findFirst({ where: { id, shop } });
148	        if (!existing) return { error: "Chart not found" };
149	
150	        await db.sizeChart.updateMany({
151	          where: { id, shop },
152	          data: {
153	            name: name.trim(),
154	            category,
155	            status,
156	            data: JSON.stringify(parsedData),
157	          },
158	        });
159	        return { ok: true, message: "Chart saved successfully" };
160	      }
161	
162	      case "toggle-status": {
163	        const chart = await db.sizeChart.findFirst({ where: { id, shop } });
164	        if (!chart) return { error: "Chart not found" };
165	        const newStatus = chart.status === "active" ? "draft" : "active";
166	        await db.sizeChart.updateMany({ where: { id, shop }, data: { status: newStatus } });
167	        return {
168	          ok: true,
169	          message: newStatus === "active" ? "Chart published" : "Chart unpublished",
170	          newStatus,
171	        };
172	      }
173	
174	      case "duplicate": {
175	        const source = await db.sizeChart.findFirst({ where: { id, shop } });
176	        if (!source) return { error: "Chart not found" };
177	
178	        const copy = await db.sizeChart.create({
179	          data: {
180	            shop,
181	            name: `${source.name} (Copy)`,
182	            type: source.type,
183	            category: source.category,
184	            status: "draft",
185	            data: source.data,
186	          },
187	        });
188	        return redirect(`/app/size-charts/${copy.id}?saved=1`);
189	      }
190	
191	      case "add-assignment": {
192	        const assignmentType = formData.get("assignmentType") as string;
193	        const assignmentValue = formData.get("assignmentValue") as string;
194	
195	        if (!assignmentValue?.trim()) {
196	          return { error: "Assignment value is required" };
197	        }
198	
199	        await db.chartAssignment.upsert({
200	          where: {
201	            shop_sizeChartId_assignmentType_assignmentValue: {
202	              shop,
203	              sizeChartId: id,
204	              assignmentType,
205	              assignmentValue: assignmentValue.trim(),
206	            },
207	          },
208	          create: {
209	            shop,
210	            sizeChartId: id,
211	            assignmentType,
212	            assignmentValue: assignmentValue.trim(),
213	          },
214	          update: {},
215	        });
216	        return { ok: true, message: "Assignment added" };
217	      }
218	
219	      case "remove-assignment": {
220	        const assignmentId = formData.get("assignmentId") as string;
221	        await db.chartAssignment.deleteMany({
222	          where: { id: assignmentId, shop },
223	        });
224	        return { ok: true, message: "Assignment removed" };
225	      }
226	
227	      case "delete": {
228	        await db.sizeChart.deleteMany({ where: { id, shop } });
229	        return redirect("/app/size-charts");
230	      }
231	
232	      default:
233	        return { error: "Unknown action" };
234	    }
235	  } catch (error) {
236	    const message =
237	      error instanceof Error ? error.message : "An unexpected error occurred";
238	    if (message.includes("Unique constraint")) {
239	      return { error: "A chart with this name already exists." };
240	    }
241	    return { error: message };
242	  }
243	};
